import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md","lastUpdated":1788344355000}`),a={name:`reference/environment.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to “Environment variables”">​</a></h1><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>RUSTPAD_URL</code></td><td>yes</td><td>—</td><td>Base URL of the Rustpad instance</td></tr><tr><td><code>RUSTPAD_READ_ONLY</code></td><td>no</td><td><code>false</code></td><td><code>true</code> registers only the read tools</td></tr><tr><td><code>RUSTPAD_INSECURE_TLS</code></td><td>no</td><td><code>false</code></td><td><code>true</code> accepts self-signed certificates, scoped</td></tr><tr><td><code>ELICITATION</code></td><td>no</td><td><code>true</code></td><td><code>false</code> falls back to the two-call token. <strong>Not prefixed</strong></td></tr></tbody></table><h2 id="rustpad-url" tabindex="-1">RUSTPAD_URL <a class="header-anchor" href="#rustpad-url" aria-label="Permalink to “RUSTPAD_URL”">​</a></h2><p>One URL for the HTTP API, the WebSocket endpoint and the share links in tool results. Validated on start: <code>http:</code>/<code>https:</code> only, no embedded credentials, no query or fragment; trailing slashes are stripped. Plain <code>http</code> to a non-local host logs a warning — pad content would travel unencrypted. Without the variable the server still starts, lists its tools, and fails every call with setup instructions (so registries and inspectors can introspect it).</p><h2 id="rustpad-read-only" tabindex="-1">RUSTPAD_READ_ONLY <a class="header-anchor" href="#rustpad-read-only" aria-label="Permalink to “RUSTPAD_READ_ONLY”">​</a></h2><p><code>true</code>, <code>TRUE</code>, <code>1</code> or <code>yes</code>, with surrounding whitespace ignored. Read leniently on purpose: this switch is a protection, and a typo that silently registered the write tools would never be reported. When active, the five write tools are not registered at all — the connection never advertises them.</p><h2 id="rustpad-insecure-tls" tabindex="-1">RUSTPAD_INSECURE_TLS <a class="header-anchor" href="#rustpad-insecure-tls" aria-label="Permalink to “RUSTPAD_INSECURE_TLS”">​</a></h2><p>Compared against exactly the string <code>true</code>. Disables certificate validation for the configured connection only, via a dedicated dispatcher — never process-wide. The server prints a banner on start when this is active.</p><h2 id="elicitation" tabindex="-1">ELICITATION <a class="header-anchor" href="#elicitation" aria-label="Permalink to “ELICITATION”">​</a></h2><p>Whether a client that <em>can</em> show a dialog is asked before a guarded tool acts. Default <code>true</code>. <code>false</code> takes the two-call-token path instead — it does not remove the guard, and a server started with it off says so on one startup line.</p><p>Unlike every other variable here it carries <strong>no prefix</strong>, so one <code>export ELICITATION=false</code> reaches every MCP server in the same environment. That is the point of it and also its risk; see <a href="/guide/approval">Asking a person</a>.</p><p>Unlike every other boolean here it is also <strong>fatal on anything else</strong>: <code>1</code>, <code>off</code> or a typo stop the server with exit code 1 rather than falling back to the default. It is the only variable of this family that defaults to <em>on</em>, and a typo that fell back would leave the dialog running while the operator believed it was off.</p><p>Values are trimmed and matched case-insensitively, so <code>False</code> and <code>false</code> both work — the strictness is about which words count, not about their shape.</p><p>There are no secrets: Rustpad has no authentication, and this server therefore handles no tokens or passwords at all.</p><h2 id="narrowing-the-tool-list" tabindex="-1">Narrowing the tool list <a class="header-anchor" href="#narrowing-the-tool-list" aria-label="Permalink to “Narrowing the tool list”">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>RUSTPAD_ALLOW_TOOLS</code></td><td>no</td><td>Tool names, <code>list_*</code> prefixes or <code>essential</code>; only these register</td></tr><tr><td><code>RUSTPAD_DENY_TOOLS</code></td><td>no</td><td>Same syntax; subtracted from whatever the allow list left</td></tr></tbody></table><p>Both are comma-separated. Each entry is either an exact tool name or a prefix with a single trailing <code>*</code>. Entries are trimmed and matched case-insensitively; empty entries are ignored, and a value that is empty or only whitespace counts as unset — <code>RUSTPAD_ALLOW_TOOLS=</code> in a compose file does not mean &quot;allow nothing&quot;. <code>essential</code> is recognised only in the allow list, and selects <code>get_document</code>, <code>get_document_info</code>, <code>create_document</code>, <code>set_document</code>, <code>append_to_document</code>.</p><p><strong>An entry that matches no tool aborts startup</strong>, naming the entry and listing the valid names, as does a malformed pattern such as <code>*_x</code> or <code>list_*_x</code>. The alternative — ignoring the entry — leaves a tool missing from <code>tools/list</code> with nothing pointing at the cause. If both lists together remove everything, the server refuses to start rather than offering an empty tool list.</p><p>Under <code>RUSTPAD_READ_ONLY</code>, an exact write-tool name in the allow list is an error naming the read-only setting rather than &quot;unknown tool&quot;; a pattern covering write tools is accepted and merely contributes nothing, with a warning on stderr. Deny entries are exempt: denying an already-suppressed tool is how a defensive list is written.</p>`,19)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};